arguments.command:
curl -s -X POST https://slack.com/api/users.list -H "Authorization: Bearer <TOKEN>" -d "limit=0" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print('ERR', d)
else:
    for u in d['members']:
        n=u.get('profile',{}).get('real_name','') or ''
        dn=u.get('deleted') and ' (deleted)'
        if 'leo' in n.lower() or 'park' in n.lower():
            print(u['id'], repr(n), dn or '')
"

